package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaViDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Quy y khỏi ác nghiệp của tôi", "Ôi Allah, tôi cầu xin Ngài nơi ẩn náu khỏi sự xấu xa của những gì tôi đã làm và khỏi sự xấu xa của những gì tôi chưa làm.", "Một dua của Nhà tiên tri ﷺ, theo Aisha (RA).", "Bảo vệ khỏi hậu quả của cả những gì đã làm và những gì chưa làm."),
        "dua_jahdil_bala" to DuaText("Nơi ẩn náu khỏi những thử thách nghiêm trọng", "Ôi Allah, tôi cầu xin Ngài che chở khỏi thử thách khắc nghiệt, khỏi bị khốn khổ, khỏi một sắc lệnh xấu xa và khỏi sự hả hê của kẻ thù.", "Trốn tránh những thử thách khắc nghiệt và sự hả hê của kẻ thù.", "Nhà tiên tri ﷺ đã tìm nơi ẩn náu khỏi bốn điều này."),
        "dua_fitnat_ghina_faqr" to DuaText("Quy y khỏi những thử thách của giàu sang và nghèo đói", "Lạy Allah, con cầu xin Ngài che chở khỏi sự lười biếng và tuổi già, khỏi tội lỗi và nợ nần, khỏi sự xét xử và trừng phạt dưới mồ, khỏi sự xét xử và trừng phạt của Lửa, khỏi cái ác của thử thách của cải và khỏi thử thách của nghèo đói.", "Trốn tránh những thử thách của nấm mồ, Địa ngục, giàu nghèo (một phần của dua).", "Một sự ẩn náu toàn diện từ Nhà tiên tri ﷺ."),
        "dua_kufr_faqr" to DuaText("Quy y khỏi sự hoài nghi và nghèo đói", "Ôi Allah, tôi cầu xin Ngài che chở khỏi sự hoài nghi và nghèo đói, và tôi cầu xin Ngài che chở khỏi sự trừng phạt của nấm mộ. Không có thần nào ngoại trừ Bạn.", "Ba lần sáng và tối.", "Abu Bakrah (RA) đã nghe Nhà tiên tri ﷺ nói điều này."),
        "dua_sharri_sami" to DuaText("Trốn tránh sự ác của các giác quan của tôi", "Lạy Allah, con cầu xin Ngài che chở khỏi điều ác trong thính giác, điều ác của thị giác, điều ác của lưỡi, điều ác của trái tim và điều ác của ham muốn của con.", "Đã dạy cho Shakal ibn Humayd (RA).", "Một dua để bảo vệ tứ chi và bản thân khỏi tội lỗi."),
        "dua_hadm_gharaq" to DuaText("Quy y khỏi cái chết đột ngột và tai nạn", "Ôi Allah, tôi cầu xin Ngài nơi trú ẩn để khỏi bị nghiền nát (bởi một tòa nhà), khỏi bị rơi từ trên cao, chết đuối, bỏng rát và tuổi già; khỏi việc Shaytan dẫn con lạc lối vào lúc chết, khỏi chết khi chạy trốn khỏi con đường của Ngài, và khỏi chết vì bị nọc độc (độc độc).", "Trốn tránh tai nạn và cái chết đau thương.", "Một nơi ẩn náu từ Nhà tiên tri ﷺ."),
        "dua_ju_khiyanah" to DuaText("Trốn tránh nạn đói và sự phản bội", "Lạy Allah, con cầu xin Ngài che chở khỏi cơn đói vì đó là một người bạn đồng hành xấu xa, và con cầu xin Ngài che chở khỏi sự phản bội vì đó là một người bạn tâm tình xấu xa.", "Trốn tránh nạn đói và sự phản bội.", "Một nơi ẩn náu từ Nhà tiên tri ﷺ."),
        "dua_huda_tuqa" to DuaText("Hướng dẫn, Sùng đạo, Khiết tịnh và Đầy đủ", "Ôi Allah, tôi cầu xin Ngài hướng dẫn, sùng đạo, khiết tịnh và tự túc.", "Một bản dua ngắn gọn, đầy đủ về Nhà tiên tri ﷺ.", "Bốn phước lành nền tảng của tôn giáo và thế giới này."),
        "dua_aslih_li_dini" to DuaText("Chỉnh sửa tôn giáo của tôi, thế giới và sau này", "Ôi Allah, hãy điều chỉnh tôn giáo của tôi, đó là sự bảo vệ cho mọi công việc của tôi; sắp xếp lại cuộc sống trần tục của tôi, trong đó là sinh kế của tôi; và thiết lập ngay sau đây của tôi, nơi tôi sẽ quay trở lại. Xin hãy làm cho cuộc sống của tôi gia tăng mọi điều tốt lành, và làm cho cái chết giúp tôi thoát khỏi mọi điều ác.", "Cải cách tôn giáo, đời này và đời sau - cả ba.", "Một bản dua toàn diện của Nhà tiên tri ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Hướng trái tim chúng tôi đến sự vâng lời của bạn", "Ôi Allah, Người xoay trái tim, hãy hướng trái tim chúng tôi đến sự vâng lời của Ngài.", "Một dua để giữ cho trái tim vững vàng trong sự vâng phục.", "Trái tim của mọi người đều ở giữa hai ngón tay của Đấng Nhân Từ Nhất."),
        "dua_jannah_nar" to DuaText("Cầu xin Jannah, Nơi trú ẩn khỏi lửa", "Ôi Allah, tôi cầu xin Ngài về Thiên đường và tôi tìm nơi ẩn náu trong Ngài khỏi Lửa.", "Sau tashahhud hoặc bất cứ lúc nào.", "Nhà tiên tri ﷺ đã nói: bộ đôi của chúng ta cũng xoay quanh vấn đề này."),
        "dua_khayri_kullih" to DuaText("Tất cả đều tốt, bây giờ và sau này", "Ôi Allah, tôi cầu xin Ngài mọi điều tốt lành - ngay lập tức và tạm thời, những gì tôi biết và những gì tôi không biết - và tôi cầu xin Ngài che chở khỏi mọi điều ác - ngay lập tức và tạm thời, những gì tôi biết và những gì tôi không biết. Ôi Allah, tôi cầu xin Ngài ban cho Thiên đường và bất cứ lời nói và hành động nào đưa tôi đến gần nó, và tôi cầu xin Ngài nơi trú ẩn khỏi Lửa cũng như bất cứ lời nói và hành động nào đưa tôi đến gần nó.", "Nhà tiên tri ﷺ đã dạy dua toàn diện này cho Aisha (RA) (một phần của dua).", "Một dua tập hợp mọi điều tốt đẹp."),
        "dua_ihdini_saddidni" to DuaText("Hướng dẫn tôi và giữ cho tôi đứng thẳng", "Ôi Allah, hãy hướng dẫn tôi và giữ cho tôi đi đúng hướng.", "Nhà tiên tri ﷺ đã dạy điều đó cho Ali (RA).", "Hãy coi sự hướng dẫn như được hướng dẫn dọc theo một con đường, và sadad như độ thẳng của một mũi tên."),
        "dua_hubbaka" to DuaText("Cầu xin tình yêu của Allah", "Ôi Allah, tôi cầu xin Ngài tình yêu của Ngài, tình yêu của những người yêu mến Ngài và những việc làm đưa tôi đến với tình yêu của Ngài. Lạy Allah, xin hãy làm cho tình yêu của Ngài trở nên thân thương với con hơn chính con, gia đình con và nước lạnh.", "Dua của Dawud (AS) có liên quan đến Nhà tiên tri ﷺ.", "Tình yêu của Allah là sự giàu có lớn nhất."),
        "dua_filal_khayrat" to DuaText("Làm điều thiện và bỏ điều ác", "Ôi Allah, tôi cầu xin Ngài cho phép tôi làm những việc tốt, bỏ những việc xấu và yêu thương người nghèo, và xin Ngài tha thứ và thương xót tôi. Và khi Ngài dự định xét xử một dân tộc, xin hãy đưa con đi mà không cần xét xử. Con xin Chúa tình yêu, tình yêu của những người yêu mến Chúa, và tình yêu của những việc làm đưa con đến gần tình yêu của Chúa.", "Allah đã dạy điều này cho Nhà tiên tri ﷺ trong một giấc mơ.", "Nhà tiên tri ﷺ đã nói: đó là sự thật, vì vậy hãy học và dạy nó."),
        "dua_bi_ilmikal_ghayb" to DuaText("Hãy để tôi sống khi cuộc sống vẫn tốt đẹp", "Ôi Allah, bằng sự hiểu biết của Ngài về những điều vô hình và quyền năng của Ngài đối với tạo vật - hãy giữ cho tôi sống chừng nào Ngài biết cuộc sống tốt đẹp hơn cho tôi và hãy đưa tôi đi khi Ngài biết cái chết là tốt hơn cho tôi. Ôi Allah, tôi cầu xin Ngài sự kính sợ Ngài ở nơi riêng tư và nơi công cộng, lời nói của sự thật trong sự hài lòng và tức giận, và sự chừng mực trong nghèo đói và giàu có.", "Lời cầu nguyện của Ammar ibn Yasir (RA) (phần mở đầu).", "Nhà tiên tri ﷺ đã thực hiện điều này trong lời cầu nguyện."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Ôi Allah, tôi cầu xin Ngài, vì mọi lời khen ngợi đều thuộc về Ngài; không có thần nào ngoại trừ Ngài, Đấng ban ân huệ, Đấng sáng tạo trời và đất. Hỡi người sở hữu uy nghiêm và danh dự, Hỡi Đấng hằng sống, Hỡi Đấng duy trì!", "Nhà tiên tri ﷺ cho biết người đàn ông này đã thực hiện dua với Tên vĩ đại nhất của Allah.", "Một dua được thực hiện với Tên này được trả lời."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Ôi Allah, tôi cầu xin Ngài vì tôi làm chứng rằng Ngài là Allah; không có thần thánh nào ngoại trừ Ngài, Đấng Duy nhất, Đấng Tự túc, Đấng không sinh ra cũng không sinh ra, và không có đấng nào có thể so sánh được với Ngài.", "Nhà tiên tri ﷺ cho biết người đàn ông này đã hỏi Allah bằng Tên vĩ đại nhất của Ngài.", "Khi nó xin thì Ngài ban cho; khi được nó gọi, Ngài trả lời."),
        "dua_thabbitni_hadiyan" to DuaText("Làm cho tôi vững chắc, được hướng dẫn và hướng dẫn", "Ôi Allah, hãy khiến tôi vững vàng và khiến tôi trở thành người hướng dẫn và được hướng dẫn.", "Nhà tiên tri ﷺ đã tạo ra bản dua này cho Jarir (RA) (tự nói là 'thabbitni').", "Dua ban đầu của Jarir (RA) sử dụng từ 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Hãy tha thứ cho tôi và chấp nhận sự ăn năn của tôi", "Lạy Chúa, xin tha thứ cho con và chấp nhận sự ăn năn của con. Quả thật, Ngài là Đấng Chấp nhận sự ăn năn, Đấng Thương Xót.", "Một trăm lần trong một lần — cách thực hành của Nhà tiên tri ﷺ.", "Những người bạn đồng hành đã đếm được Nhà tiên tri ﷺ đã nói điều đó hàng trăm lần trong một lần ngồi."),
        "dua_rafiq_ala" to DuaText("Dua của người hấp hối", "Ôi Allah, hãy tha thứ cho tôi, thương xót tôi và tham gia cùng tôi với Người bạn đồng hành tối cao.", "Câu cuối cùng của Nhà tiên tri ﷺ — để người bệnh tự nói.", "Nhà tiên tri ﷺ đã thực hiện điều này vào thời điểm ông qua đời."),
        "dua_la_bas_tahur" to DuaText("An ủi người bệnh: Thanh lọc", "Không có hại; đó là một sự thanh lọc (khỏi tội lỗi), nếu Allah muốn.", "Để an ủi người bệnh khi đến thăm.", "Nhà tiên tri ﷺ đã nói điều này khi đến thăm người bệnh."),
        "dua_talqeen" to DuaText("Talqeen cho người hấp hối", "Không ai có quyền được tôn thờ ngoại trừ Allah.", "Hãy đọc kinh kalimah gần người sắp chết (đừng ép họ nói).", "Lời cuối cùng của ai là 'La ilaha illallah' sẽ vào Thiên đường (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Thay vì mong muốn cái chết", "Ôi Allah, hãy giữ cho tôi sống chừng nào cuộc sống còn tốt hơn cho tôi và đưa tôi đi khi cái chết còn tốt hơn cho tôi.", "Thay vì mong muốn cái chết trong khó khăn.", "Nhà tiên tri ﷺ cấm ước muốn cái chết và thay vào đó đã dạy điều này."),
        "dua_for_one_i_cursed" to DuaText("Dành cho người tôi làm tổn thương bằng lời nói", "Lạy Allah, bất kỳ tín đồ nào mà Ta đã xúc phạm, hãy coi đó là phương tiện để họ được gần gũi với Ngài vào Ngày Phục sinh.", "Đối với người mà bạn đã nói xấu trong lúc tức giận.", "Bản dua của Nhà tiên tri ﷺ."),
        "dua_praising_someone" to DuaText("Khi khen ngợi ai đó", "Tôi coi điều này điều nọ là như thế, và Allah là Người phán xét của anh ấy, và tôi không đảm bảo sự trong sạch của bất kỳ ai trước Allah.", "Khi khen ngợi ai đó, thay vì cường điệu.", "Nhà tiên tri ﷺ đã dạy nghi thức khen ngợi này."),
        "dua_being_praised" to DuaText("Khi bạn được khen ngợi", "Ôi Allah, đừng bắt tôi phải chịu trách nhiệm về những gì họ nói và hãy tha thứ cho tôi về những gì họ không biết.", "Khi nghe mình khen ngợi – thực hành Người bạn đồng hành (RA).", "Một cách để tránh kiêu ngạo khi được khen ngợi."),
        "dua_non_muslim_sneezes" to DuaText("Khi một người không theo đạo Hồi hắt hơi", "Có thể Allah hướng dẫn bạn và giải quyết công việc của bạn đúng đắn.", "Khi một người không theo đạo Hồi hắt hơi và nói 'Alhamdulillah'.", "Người Do Thái sẽ hắt hơi gần Nhà tiên tri ﷺ với hy vọng ông ấy sẽ nói 'Yarhamukallah', và ông ấy sẽ nói điều này."),
        "dua_reply_ahl_kitab_salam" to DuaText("Trả lời Salam của Người Sách", "Và trên bạn.", "Khi Người của Sách chào bằng salam.", "Lời chỉ dẫn của Nhà tiên tri ﷺ."),
        "dua_fasting_invited" to DuaText("Khi được mời khi đang nhịn ăn", "Tôi đang nhịn ăn.", "Khi được mời khi đang nhịn ăn, hoặc khi có ai đó cãi vã với bạn.", "Nếu người nhịn ăn nhận lời mời thì nên cầu nguyện cho chủ nhà."),
        "dua_for_who_gave_drink" to DuaText("Dành cho ai cho tôi ăn", "Ôi Allah, hãy cho người đã cho tôi ăn và cho người đã cho tôi uống.", "Đối với bất cứ ai cho bạn thức ăn hoặc đồ uống.", "Nhà tiên tri ﷺ đã thực hiện bản dua này cho al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Lời chào Eid", "Cầu mong Allah chấp nhận (việc tốt) từ chúng tôi và từ bạn.", "Với nhau vào ngày Eid - tục lệ của những người bạn đồng hành cao quý (RA).", "Những người bạn đồng hành đã nói điều này khi họ gặp nhau vào dịp Eid."),
        "dua_wedding_night" to DuaText("Dành cho cô dâu sau Nikah", "Ôi Allah, tôi cầu xin Ngài những điều tốt lành cho cô ấy cũng như những điều tốt đẹp về bản chất mà Ngài đã tạo ra cô ấy, và tôi cầu xin Ngài che chở cho cô ấy khỏi cái ác của cô ấy và cái ác của bản chất mà Ngài đã tạo ra cô ấy.", "Sau nikah, đặt tay lên trán người vợ.", "Lời dạy ﷺ của Nhà tiên tri — phước lành trong hôn nhân."),
        "dua_istisqa_ibadak" to DuaText("Nước cho người hầu và động vật của bạn", "Lạy Allah, xin ban nước cho các tôi tớ và súc vật của Ngài, truyền bá lòng thương xót của Ngài và ban sự sống cho vùng đất chết của Ngài.", "Cầu mưa (istisqa).", "Nhà tiên tri ﷺ đã làm điều này để cầu mưa."),
        "dua_seeing_clouds" to DuaText("Nhìn thấy đám mây đen", "Ôi Allah, tôi cầu xin Ngài nơi ẩn náu khỏi tội lỗi của nó.", "Khi nhìn thấy những đám mây đen trên bầu trời; nếu trời mưa, hãy nói 'Allahumma sayyiban nafi'a'.", "Khi nhìn thấy những đám mây, Nhà tiên tri ﷺ sẽ bỏ việc đang làm và thực hiện điều này."),
        "dua_jamarat" to DuaText("Ném đá Jamarat", "Allah là Đấng vĩ đại nhất.", "Với mỗi viên sỏi được ném đi.", "Nhà tiên tri ﷺ nói takbir với mỗi viên sỏi, sau đó, jamrah thứ nhất và thứ hai đối mặt với Qiblah và tạo thành một dua dài."),
        "dua_rabbi_ainni" to DuaText("Lạy Chúa, xin giúp con chứ đừng chống lại con", "Lạy Chúa, xin hãy giúp con và đừng giúp người khác chống lại con, ban cho con chiến thắng và đừng ban cho người khác chiến thắng con, lập kế hoạch cho con và đừng lập kế hoạch chống lại con, hướng dẫn con và giúp con dễ dàng hướng dẫn, và giúp con chống lại bất cứ ai làm sai với con.", "Bản dua toàn diện của Nhà tiên tri ﷺ (phần mở đầu).", "Một dua tập hợp mọi sự giúp đỡ trong tôn giáo và thế giới này."),
        "dua_ati_nafsi_taqwaha" to DuaText("Hãy ban cho tâm hồn tôi Taqwa", "Ôi Allah, hãy ban cho linh hồn tôi lòng đạo đức và thanh lọc nó, vì Ngài là người tốt nhất để thanh lọc nó. Bạn là Người bảo vệ và Chủ nhân của nó.", "Để cải cách và thanh lọc bản thân.", "Nhà tiên tri ﷺ đã từng làm bộ dua này."),
        "dua_iqsim_lana_khashyatik" to DuaText("Hãy cho chúng tôi nỗi sợ hãi về bạn như vậy", "Lạy Allah, xin ban cho chúng con đủ sự sợ hãi trước Ngài để đến giữa chúng con và không vâng lời Ngài, đủ vâng lời để đưa chúng con đến Thiên đường của Ngài và đủ chắc chắn để khiến chúng con dễ dàng gánh chịu những tai họa trên thế giới này. Chúng ta hãy tận hưởng thính giác, thị giác và sức mạnh của mình miễn là Ngài giữ cho chúng ta sống sót và làm cho chúng tồn tại lâu hơn chúng ta. Hãy trả thù những người đã đối xử tệ với chúng ta, giúp chúng ta chống lại kẻ thù của mình, đừng để tai họa xảy đến với tôn giáo của chúng ta, đừng biến thế giới này thành mối quan tâm lớn nhất của chúng ta hoặc giới hạn hiểu biết của chúng ta, và đừng đặt lên chúng ta những kẻ không hề thương xót chúng ta.", "Khi đứng dậy sau một cuộc tụ họp - Nhà tiên tri ﷺ hiếm khi đứng dậy mà không thực hiện điều này.", "Một sự dua toàn diện vì lợi ích của tôn giáo, thế giới này và Đời sau."),
        "dua_infani_bima_allamtani" to DuaText("Mang lại lợi ích cho tôi với những gì bạn đã dạy tôi", "Ôi Allah, hãy giúp tôi với những gì bạn đã dạy tôi, hãy dạy tôi những gì sẽ có lợi cho tôi và tăng thêm kiến ​​​​thức cho tôi.", "Trong khi tìm kiếm kiến ​​thức hoặc trước khi học tập.", "Một dua cho kiến ​​​​thức có lợi và hành động theo nó."),
    )
}
